MAX=(1<<62)-1
class Stream:
 def __init__(self,id):self.id=id;self.high=0;self.send=0;self.final=None;self.reset=None;self.stop=None;self.bytes={}
def model(body,bl,ul,lb,lu,slim,clim):
 opened=[0,0];used=0;streams={};pos=0
 def get(id):
  if id not in streams:streams[id]=Stream(id)
  return streams[id]
 def recv(id,start):
  mod=id&3;idx=id>>2
  if mod==0:
   if idx>=bl:raise E('STREAM_LIMIT_ERROR')
   opened[0]=max(opened[0],idx+1)
  elif mod==2:
   if idx>=ul:raise E('STREAM_LIMIT_ERROR')
   opened[1]=max(opened[1],idx+1)
  elif mod==1:
   if idx>=lb:raise E('STREAM_STATE_ERROR')
  else:raise E('STREAM_STATE_ERROR')
  return get(id)
 def send(id,start):
  mod=id&3;idx=id>>2
  if mod==0:
   if idx>=bl:raise E('STREAM_LIMIT_ERROR')
   opened[0]=max(opened[0],idx+1)
  elif mod==1:
   if idx>=lb:raise E('STREAM_STATE_ERROR')
  elif mod==3:
   if idx>=lu:raise E('STREAM_STATE_ERROR')
  else:raise E('STREAM_STATE_ERROR')
  return get(id)
 class E(Exception):
  def __init__(self,s):self.s=s
 def rv():
  nonlocal pos
  b=body[pos];w=1<<(b>>6)
  if pos+w>len(body):raise E('FRAME_ENCODING_ERROR')
  v=b&63
  for i in range(1,w):v=(v<<8)|body[pos+i]
  pos+=w;return v
 try:
  if not body:raise E('FRAME_ENCODING_ERROR')
  while pos<len(body):
   st=pos;t=rv()
   if t>=0x40 or ([1,2,4,8].index(1<<(body[st]>>6))) != 1: pass
   if t==0x0f:
    id=rv();off=rv();ln=rv()
    if pos+ln>len(body):raise E('FRAME_ENCODING_ERROR')
    data=body[pos:pos+ln];pos+=ln
    if off>MAX-ln:raise E('FRAME_ENCODING_ERROR')
    end=off+ln
    s=recv(id,st);old=s.high
    if s.final is not None:
     if end>s.final:raise E('FINAL_SIZE_ERROR')
     if end!=s.final:raise E('FINAL_SIZE_ERROR')
    if end<s.high:raise E('FINAL_SIZE_ERROR')
    s.final=end
    cand=max(s.high,end)
    if cand>slim:raise E('FLOW_CONTROL_ERROR')
    delta=cand-old
    if delta>clim-used:raise E('FLOW_CONTROL_ERROR')
    s.high=cand;used+=delta
    if s.reset is None:
     for i,b in enumerate(data):
      p=off+i
      if p in s.bytes and s.bytes[p]!=b:raise E('PROTOCOL_VIOLATION')
     for i,b in enumerate(data):s.bytes[off+i]=b
   elif t==0x04:
    id=rv();err=rv();fin=rv();s=recv(id,st)
    if fin<s.high:raise E('FINAL_SIZE_ERROR')
    if s.final is not None and fin!=s.final:raise E('FINAL_SIZE_ERROR')
    cand=fin
    if cand>slim:raise E('FLOW_CONTROL_ERROR')
    delta=cand-s.high
    if delta>clim-used:raise E('FLOW_CONTROL_ERROR')
    used+=delta;s.high=cand;s.final=fin
    if s.reset is None:s.reset=err
   elif t==0x05:
    id=rv();err=rv();s=send(id,st)
    if s.stop is None:s.stop=err
   elif t==0x11:
    id=rv();mx=rv();s=send(id,st)
    s.send=max(s.send,mx)
   elif t==0x15:
    id=rv();lim=rv();s=recv(id,st)
   elif t==0x01:pass
   else:raise E('FRAME_ENCODING_ERROR')
  return ('OK',opened,used,streams)
 except E as e:return (e.s,None,None,None)
